{#- Generated by `pv policy compile` from policy/policy.yaml. Do not edit.
    on-run-end: create the purpose table functions (BigQuery TABLE FUNCTION, DuckDB table macro) over the purpose
    views. Skipped for a routine whose view does not exist yet (the snapshot replay runs before the first build).
    The functions read only their own purpose dataset, whose views are authorized on the source datasets. -#}
{% macro create_purpose_routines() %}
  {%- if execute -%}
  {%- set routines = [
    {'dataset': 'peoplevault_purpose_employee_relations', 'view': 'employees', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_employee_relations.employees_in_org_units`(p_org_units ARRAY<STRING>) as (select employee_ref, full_name, work_email, job_title, job_level, org_unit, location, employment_status, hire_date, termination_date, is_restricted from `{project}.peoplevault_purpose_employee_relations.employees` where org_unit in unnest(p_org_units))', 'duckdb': 'create or replace macro peoplevault_purpose_employee_relations.employees_in_org_units(p_org_units) as table select employee_ref, full_name, work_email, job_title, job_level, org_unit, location, employment_status, hire_date, termination_date, is_restricted from peoplevault_purpose_employee_relations.employees where list_contains(p_org_units, org_unit)'},
    {'dataset': 'peoplevault_purpose_employee_relations', 'view': 'employees', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_employee_relations.profile`(p_org_units ARRAY<STRING>, p_employee_ref STRING) as (select employee_ref, full_name, work_email, personal_email, phone, birth_date, hire_date, termination_date, employment_status, job_title, job_level, org_unit, location, is_restricted, base_salary, bonus_target_pct, currency, rating, review_text, cycle, leave_type, leave_category, leave_reason, accommodation_note from `{project}.peoplevault_purpose_employee_relations.employees` where org_unit in unnest(p_org_units) and employee_ref = p_employee_ref)', 'duckdb': 'create or replace macro peoplevault_purpose_employee_relations.profile(p_org_units, p_employee_ref) as table select employee_ref, full_name, work_email, personal_email, phone, birth_date, hire_date, termination_date, employment_status, job_title, job_level, org_unit, location, is_restricted, base_salary, bonus_target_pct, currency, rating, review_text, cycle, leave_type, leave_category, leave_reason, accommodation_note from peoplevault_purpose_employee_relations.employees where list_contains(p_org_units, org_unit) and employee_ref = p_employee_ref'},
    {'dataset': 'peoplevault_purpose_team_management', 'view': 'employees', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_team_management.direct_reports`(p_manager_key STRING) as (select employee_ref, full_name, work_email, job_title, job_level, org_unit, employment_status from `{project}.peoplevault_purpose_team_management.employees` where manager_key = p_manager_key)', 'duckdb': 'create or replace macro peoplevault_purpose_team_management.direct_reports(p_manager_key) as table select employee_ref, full_name, work_email, job_title, job_level, org_unit, employment_status from peoplevault_purpose_team_management.employees where manager_key = p_manager_key'},
    {'dataset': 'peoplevault_purpose_team_management', 'view': 'employees', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_team_management.report_profile`(p_manager_key STRING, p_employee_ref STRING) as (select employee_ref, full_name, work_email, hire_date, employment_status, job_title, job_level, org_unit, location, base_salary, bonus_target_pct, currency, rating, review_text, cycle from `{project}.peoplevault_purpose_team_management.employees` where manager_key = p_manager_key and employee_ref = p_employee_ref)', 'duckdb': 'create or replace macro peoplevault_purpose_team_management.report_profile(p_manager_key, p_employee_ref) as table select employee_ref, full_name, work_email, hire_date, employment_status, job_title, job_level, org_unit, location, base_salary, bonus_target_pct, currency, rating, review_text, cycle from peoplevault_purpose_team_management.employees where manager_key = p_manager_key and employee_ref = p_employee_ref'},
    {'dataset': 'peoplevault_purpose_privacy_compliance', 'view': 'directory', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_privacy_compliance.identity_lookup`(p_q STRING) as (select employee_ref, full_name, work_email, org_unit, employment_status from `{project}.peoplevault_purpose_privacy_compliance.directory` where (starts_with(lower(full_name), lower(p_q)) or starts_with(lower(work_email), lower(p_q))) order by full_name limit 20)', 'duckdb': 'create or replace macro peoplevault_purpose_privacy_compliance.identity_lookup(p_q) as table select employee_ref, full_name, work_email, org_unit, employment_status from peoplevault_purpose_privacy_compliance.directory where (starts_with(lower(full_name), lower(p_q)) or starts_with(lower(work_email), lower(p_q))) order by full_name limit 20'},
    {'dataset': 'peoplevault_purpose_legal_hold_management', 'view': 'directory', 'bigquery': 'create or replace table function `{project}.peoplevault_purpose_legal_hold_management.identity_lookup`(p_q STRING) as (select employee_ref, full_name, work_email, org_unit, employment_status from `{project}.peoplevault_purpose_legal_hold_management.directory` where (starts_with(lower(full_name), lower(p_q)) or starts_with(lower(work_email), lower(p_q))) order by full_name limit 20)', 'duckdb': 'create or replace macro peoplevault_purpose_legal_hold_management.identity_lookup(p_q) as table select employee_ref, full_name, work_email, org_unit, employment_status from peoplevault_purpose_legal_hold_management.directory where (starts_with(lower(full_name), lower(p_q)) or starts_with(lower(work_email), lower(p_q))) order by full_name limit 20'}
  ] -%}
  {%- for r in routines -%}
    {%- set rel = adapter.get_relation(database=target.database, schema=r['dataset'], identifier=r['view']) -%}
    {%- if rel is not none -%}
      {%- if target.type == 'bigquery' -%}
        {%- do run_query(r['bigquery'] | replace('{project}', target.project)) -%}
      {%- else -%}
        {%- do run_query(r['duckdb']) -%}
      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- endif -%}
{% endmacro %}
